"use client";

import { useId, useRef, useState, type ComponentProps, type ReactNode } from "react";
import { Heart, Menu, X } from "lucide-react";
import { cn } from "cn";
import { GitHubDark } from "@ridemountainpig/svgl-react";
import { Avatar } from "../components/avatar";
import { Badge } from "../components/badge";
import { Banner } from "../components/banner";
import { Button } from "../components/button";

interface NavbarProps extends ComponentProps<"header"> {
  brand?: string;
  logo?: ReactNode;
  homeHref?: string;
  links?: { label: string; href: string }[];
  activeHref?: string;
  announcement?: string;
  badge?: string;
  supportHref?: string;
  githubHref?: string;
  account?: { name: string; src?: string; href: string };
}

function Navigation({ layout, brand = "Lazy UI", logo, homeHref = "/", links = [{ label: "Components", href: "/components" }, { label: "Blocks", href: "/blocks" }], activeHref, announcement, badge = "Beta", supportHref = "https://github.com/sponsors/razeevascx", githubHref = "https://github.com/razeevascx/lazy-ui", account, className, children, ...props }: NavbarProps & { layout: "centered" | "aligned" | "floating" }) {
  const [open, setOpen] = useState(false);
  const menuId = useId();
  const toggle = useRef<HTMLButtonElement>(null);
  function closeMenu() { setOpen(false); toggle.current?.focus(); }
  return (
    <header {...props} data-slot="navbar" data-layout={layout} className={cn("@container w-full text-foreground", layout === "floating" ? "bg-transparent p-4" : "border border-border bg-background", className)}>
      {announcement && <Banner message={announcement} dismissible={false} className="border-0 border-b border-border" />}
      <div className={cn("grid grid-cols-[1fr_auto] items-center gap-4 px-5 py-4", layout === "aligned" ? "@lg:grid-cols-[auto_1fr_auto]" : "@lg:grid-cols-[1fr_auto_1fr]", layout === "floating" && "border border-border bg-card shadow-lg")}>
        <a href={homeHref} className="flex w-fit items-center gap-2 text-lg font-semibold focus-visible:outline-2 focus-visible:outline-ring">
          {logo}<span>{brand}</span>{badge && <Badge variant="neutral">{badge}</Badge>}
        </a>
        <nav aria-label="Primary navigation" className={cn("hidden items-center gap-6 @lg:flex", layout === "aligned" ? "justify-start pl-4" : "justify-center")}>
          {links.map(link => <a key={link.href} href={link.href} aria-current={activeHref === link.href ? "page" : undefined} className="text-sm text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring aria-[current=page]:text-foreground">{link.label}</a>)}
        </nav>
        <div className="flex items-center justify-end gap-2">
          {supportHref && <a href={supportHref} aria-label="Support the project" className="inline-flex size-9 items-center justify-center hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring"><Heart size={18} aria-hidden="true" /></a>}
          {githubHref && <a href={githubHref} aria-label="GitHub repository" className="inline-flex size-9 items-center justify-center hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring"><GitHubDark width={18} height={18} aria-hidden="true" /></a>}
          {account && <a href={account.href} aria-label={`${account.name}'s account`} className="focus-visible:outline-2 focus-visible:outline-ring"><Avatar name={account.name} src={account.src} size={32} /></a>}
          <Button ref={toggle} variant="ghost" className="min-h-9 px-2 @lg:hidden" aria-label={open ? "Close navigation" : "Open navigation"} aria-expanded={open} aria-controls={menuId} onClick={() => setOpen(!open)}>
            {open ? <X size={18} aria-hidden="true" /> : <Menu size={18} aria-hidden="true" />}
          </Button>
        </div>
      </div>
      <nav id={menuId} aria-label="Mobile navigation" hidden={!open} className="border-t border-border px-5 py-3 @lg:hidden" onKeyDown={event => { if (event.key === "Escape") { event.preventDefault(); closeMenu(); } }}>
        {links.map(link => <a key={link.href} href={link.href} aria-current={activeHref === link.href ? "page" : undefined} onClick={() => setOpen(false)} className="block px-2 py-3 text-sm text-muted-foreground hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring aria-[current=page]:text-foreground">{link.label}</a>)}
      </nav>
      {children}
    </header>
  );
}

export function Navbar(props: NavbarProps = {}) {
  return <Navigation {...props} layout="centered" />;
}

export function NavbarAligned(props: NavbarProps = {}) {
  return <Navigation {...props} layout="aligned" />;
}

export function NavbarFloating(props: NavbarProps = {}) {
  return <Navigation {...props} layout="floating" />;
}

"use client";

import { useState } from "react";

interface AvatarProps {
  src?: string;
  name?: string;
  size?: number;
  className?: string;
}

export function Avatar({
  src,
  name = "Alex Morgan",
  size = 48,
  className = "",
}: AvatarProps = {}) {
  const [failedSrc, setFailedSrc] = useState<string>();
  const initials = name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0])
    .join("")
    .toUpperCase();
  // Registry consumers can use any React framework and image URL.
  /* eslint-disable @next/next/no-img-element */
  return (
    <span
      role="img"
      aria-label={name}
      style={{ width: size, height: size }}
      className={`inline-flex shrink-0 items-center justify-center overflow-hidden border border-border bg-emerald-400/15 text-sm font-semibold text-emerald-300 ${className}`}
    >
      {src && failedSrc !== src ? (
        <img
          src={src}
          alt=""
          width={size}
          height={size}
          onError={() => setFailedSrc(src)}
          className="h-full w-full object-cover"
        />
      ) : (
        initials || "?"
      )}
    </span>
  );
}

import type { ComponentProps } from "react";

interface BadgeProps extends ComponentProps<"span"> {
  variant?: "neutral" | "info" | "success" | "warning" | "error" | "blue" | "purple" | "pink" | "teal" | "orange";
}

export function Badge({ children = "New release", variant = "success", className = "", ...props }: BadgeProps = {}) {
  const styles = {
    neutral: "bg-neutral-800 text-neutral-200",
    info: "bg-sky-400/10 text-sky-300",
    success: "bg-emerald-400/10 text-emerald-300",
    warning: "bg-amber-400/10 text-amber-300",
    error: "bg-red-400/10 text-red-300",
    blue: "bg-blue-400/10 text-blue-300",
    purple: "bg-purple-400/10 text-purple-300",
    pink: "bg-pink-400/10 text-pink-300",
    teal: "bg-teal-400/10 text-teal-300",
    orange: "bg-orange-400/10 text-orange-300",
  };
  return <span className={`inline-flex items-center border border-border px-2.5 py-1 text-xs font-medium ${styles[variant] ?? styles.success} ${className}`} {...props}>{children}</span>;
}

"use client";

import { useState, type ReactNode } from "react";

interface BannerProps {
  variant?: "primary" | "secondary" | "ghost" | "destructive";
  children?: ReactNode;
  message?: string;
  dismissible?: boolean;
  className?: string;
}

export function Banner({ variant = "primary", children, message = "A little update. A lot of possibilities. Explore what's new.", dismissible = true, className = "" }: BannerProps = {}) {
  const styles = {
    primary: "bg-primary text-primary-foreground",
    secondary: "bg-card text-card-foreground",
    ghost: "bg-transparent text-foreground",
    destructive: "bg-destructive text-destructive-foreground",
  };
  const [dismissed, setDismissed] = useState(false);
  if (dismissed) return null;
  return <div role="status" className={`flex items-center justify-between gap-4 border border-border px-5 py-4 text-sm ${styles[variant] ?? styles.primary} ${className}`}>
    <div>{children ?? message}</div>
    {dismissible && <button type="button" aria-label="Dismiss banner" onClick={() => setDismissed(true)} className="flex size-9 shrink-0 items-center justify-center hover:bg-black/10 focus-visible:outline-2 focus-visible:outline-current"><span aria-hidden="true">×</span></button>}
  </div>;
}

import type { ComponentProps } from "react";

interface ButtonProps extends ComponentProps<"button"> {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
}

export function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  type = "button",
  ...props
}: ButtonProps = {}) {
  const styles = {
    primary: "bg-emerald-400 text-neutral-950 hover:bg-emerald-300",
    secondary: "bg-neutral-800 text-white hover:bg-neutral-700",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
    outline: "border border-border text-white hover:bg-neutral-800",
  };
  return (
    <button
      type={type}
      className={`inline-flex min-h-11 items-center justify-center gap-2 px-5 py-2 text-sm font-semibold transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-400 disabled:pointer-events-none disabled:opacity-50 ${styles[variant] ?? styles.primary} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
}
